import { Counter as ImportedCounter } from './members.a';
export { ImportedCounter as PublicCounter };
export function make(): ImportedCounter {
    return new ImportedCounter();
}

export class Counter {
    private value: number = 0;
    static readonly label: string = 'counter';
    increment(): number {
        this.value += 1;
        return this.value;
    }
}
export interface Named {
    readonly name: string;
}
export type MaybeName = Named | undefined;

export function outer(value: number): number {
    let result = value;
    if (value > 0) {
        const delta = 2;
        result += delta;
    }
    return result;
}
export const label: string = 'scope';
